NAMES = list(ICONS)


def svg(name, style="fill"):
    """인라인 SVG. 색: 선·면 = currentColor(강조색), 채운 아이콘의 안쪽 선 = var(--bg)."""
    _, closed, inner, outer = ICONS[name]
    if style == "line":
        g = ('<g fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'
             + "".join(closed + inner + outer) + "</g>")
    else:
        g = ('<g fill="currentColor" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round">' + "".join(closed) + "</g>"
             '<g fill="none" style="stroke:var(--bg)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">' + "".join(inner) + "</g>"
             '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + "".join(outer) + "</g>")
    return f'<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">{g}</svg>'
